import{_ as t,o as e,c as a,Q as o}from"./chunks/framework.b67c47e6.js";const r="/assets/wood-bom-page.948ea75e.svg",f=JSON.parse('{"title":"Wood BoM","description":"","frontmatter":{},"headers":[],"relativePath":"guide/reports/wood_bom/index.md","filePath":"guide/reports/wood_bom/index.md","lastUpdated":1790354386000}'),n={name:"guide/reports/wood_bom/index.md"},s=o('<h1 id="wood-bom" tabindex="-1">Wood BoM <a class="header-anchor" href="#wood-bom" aria-label="Permalink to &quot;Wood BoM&quot;">​</a></h1><p>The Wood Bill of Materials generates a PDF document listing all wood and profile parts for your selected constructibles.</p><p><img src="'+r+'" alt="A page of a Wood BoM"></p><ol><li>The material, section, finish and comment of the group, with a drawing of the cross-section.</li><li>The straight parts, with a totals row.</li><li>Parts that differ only in their length share one drawing. The part of the length that changes is drawn short, between two break marks.</li><li>The length reads <strong>LENGTH</strong>. Each end has its own 0.</li><li>One row per part, with its real length.</li></ol><h2 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h2><ul><li><strong>Format:</strong> PDF (single file or ZIP with multiple PDFs)</li><li><strong>Content:</strong> All wood/profile parts with dimensions, quantities, materials, and optional drawings. Parts are grouped by material, section, finish and comment. Each group starts with a header (material, section code, finish, comment and a drawing of the cross-section), followed by a table per drawing with zone, reference, count, length, surface, volume, weight and counts per design, and a totals row.</li></ul><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>Group parts from the report in the same folder</strong></td><td>How the content is split into files (see below). Default: <em>By Batch</em>.</td></tr><tr><td><strong>Cross sections to include</strong></td><td><em>all</em> (default), <em>shaped_cross_sections</em> or <em>rectangular_cross_sections</em>: include all parts, only parts with a shaped section, or only rectangular ones.</td></tr><tr><td><strong>Combine</strong></td><td>When the output is a ZIP, also add <em>Combined.pdf</em> with all the PDFs merged.</td></tr><tr><td><strong>Cover Page</strong></td><td>Include a title page with project information. On by default.</td></tr><tr><td><strong>Designs Summary</strong></td><td>Add a summary table listing all included designs.</td></tr><tr><td><strong>Totals Table Page</strong></td><td>Add a page with total length, surface, volume and weight per material, before the tables.</td></tr><tr><td><strong>Show Profile Side Drawings</strong></td><td>Include a side and top drawing for each part with details (drillings, notches, angled cuts), with its end-cut angles. On by default.</td></tr><tr><td><strong>Group parts that differ only in length</strong></td><td>On by default. Parts with the same details and a different length share one table and one drawing, with the length shown as LENGTH. See <a href="#parts-that-differ-only-in-length">below</a>.</td></tr><tr><td><strong>Attach to Viewer as DOC</strong></td><td>Link each generated PDF to its assemblies in the Viewer. Only when the output is a ZIP.</td></tr><tr><td><strong>Contact person</strong> / <strong>Delivery address</strong></td><td>Printed on the cover page. Leave empty to use the company&#39;s.</td></tr><tr><td><strong>Materials</strong></td><td>Only include wood parts of the selected materials.</td></tr></tbody></table><h2 id="parts-that-differ-only-in-length" tabindex="-1">Parts that differ only in length <a class="header-anchor" href="#parts-that-differ-only-in-length" aria-label="Permalink to &quot;Parts that differ only in length&quot;">​</a></h2><p>With <strong>Show profile side drawings</strong> on, each wood part with a detail (a drilling, a notch, an angled end cut) gets a table and a drawing of its own. When several parts have exactly the same details and differ only in their length — the studs of a sloped wall, all with the same angled top cut — they now share <strong>one table and one drawing</strong>, with a row per part.</p><ul><li>The drawing shows the length as <strong>LENGTH</strong>, with no number. The real length of each part is in its row.</li><li>The part of the length that changes is drawn short, between two break marks.</li><li>Details before it are measured from the left end, below the drawing. Details after it are measured from the right end, above the drawing, each end with its own 0.</li><li>Only the length may differ: a different width, height, section, material, finish or comment keeps the parts apart. Details must match within 1 mm.</li><li>A part turned end for end or turned over counts as the same part. A mirrored part does not.</li><li>A group has <strong>one</strong> changing length or none. If some parts change before a detail and others after it, they form separate groups.</li></ul><p>Tables go by the part&#39;s <strong>shape</strong>, whichever way round it was modelled, not by its reference. A reference is expected to be one shape, and when it is not, the row says so in red: <em>this reference has more than one shape</em> (its rows are in separate tables) or <em>same shape as another reference</em> (separate rows of one table). In projects created before 26 September 2026, a part modelled turned round still counts as another shape.</p><p>Turn it off with <strong>Group parts that differ only in length</strong> to get one table per part again. The drawing of each part, in the viewer and in logistics, is not affected: it keeps all its numbers.</p><h2 id="grouping-modes" tabindex="-1">Grouping Modes <a class="header-anchor" href="#grouping-modes" aria-label="Permalink to &quot;Grouping Modes&quot;">​</a></h2><ul><li><strong>By Selected Panels</strong> — One single PDF with all selected content.</li><li><strong>By Phase</strong> — One PDF per phase (ZIP output).</li><li><strong>By Batch</strong> — One PDF per batch (ZIP output).</li><li><strong>By Panel</strong> — One PDF per assembly (ZIP output).</li></ul><p>When you select by part batches, the output is always one single PDF.</p>',16),i=[s];function l(d,h,g,p,c,u){return e(),a("div",null,i)}const w=t(n,[["render",l]]);export{f as __pageData,w as default};
